  ["e3150e6f2f8a994e"] = { "Segugio all'orizzonte, si muove a trenta piedi al secondo. L'unica domanda è: occhio destro o sinistro? Proprio così, <ragazzo/ragazza>, ho una mira infallibile.", "." },
  ["e3195379fe4861f8"] = { "Non abbiamo tempo per parlare! Dobbiamo pensare a quei troll!", "." },
  ["e3253541f4db25e4"] = { "<L'alto inquisitore Fairbanks solleva la sua tunica e rivela diverse orribili cicatrici.>\n\nPerché c'ero... Ero il consigliere più fidato del gran signore. Avrei dovuto capirlo... Sentivo che qualcosa non andava, eppure ho lasciato che accadesse. Ci crederesti che c'erano mille o più membri del Flagello?", "." },
  ["e3265b41ce5f9d45"] = { "La rabbia di %s esplode in una furia frenetica!", "." },
  ["e334ffbbe6e83322"] = { "Non sfuggirai alla morte!", "." },
  ["e34340678584c24a"] = { "I druidi dicono che è solo questione di tempo prima che la natura stessa scacci l'⟦Horde=Orda⟧ da Kalimdor. Eppure la corruzione continua a diffondersi nelle nostre terre, persino qui a Teldrassil.", "." },
  ["e34566939eda6618"] = { "D'accordo, beh... non montarti la testa! Ma visto che hai dimostrato la tua competenza, ora possiamo cominciare!", "." },
  ["e3490fa6ccf4be47"] = { "La raccolta è finita e le merci vengono spedite a ⟦Silithus=Silitus⟧ man mano che sono pronte. Sembra che manchi meno di un giorno perché arrivi tutto. Dopodiché basta che qualcuno suoni quel gong e apra i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Allora sì che comincia il bello.", "." },
  ["e34ba743d74b79bf"] = { "L'anziano Hammershout si trova entro le mura di ⟦Stormwind=Roccavento⟧.", "." },
  ["e34d4aeed10d1530"] = { "Non posso immagazzinare altre scorte. Ne ho più di quante ne possa gestire!", "." },
  ["e35d5b4a5270fed5"] = { "Sarà così bello riavere all'ovile la nostra pecorella smarrita, non trovi?", "." },
  ["e3600d39873bbe59"] = { "Ho sentito che a ⟦Ironforge=Forgiardente⟧ c'è una bottega gestita dagli gnomi specializzata in alchimia. Dovresti darci un'occhiata.", "." },
  ["e361f26e724ee82d"] = { "Noi ha casa d'aste in anello centrale.", "." },
  ["e3639023aafa084a"] = { "Vedo il tuo impegno, e vedo che hai compreso ciò che ti ho insegnato, {name}.", "." },
  ["e36d0c502d80c677"] = { "Grazie di cuore!", "." },
  ["e36d21b29336d08d"] = { "Adoro l'odore di ⟦Ironforge=Forgiardente⟧ al mattino! Eh? E tu di che cosa avresti bisogno, {class}?", "." },
  ["e37228ddfe3918ac"] = { "Bene, diamo un'occhiata a quest'aggeggio...", "." },
  ["e372a5032ea22add"] = { "Ah, credo che Gimble Thistlefuzz sia quello che ti serve, se vuoi imparare la professione di Incantamento. Troverai Gimble nella sua bottega, Thistlefuzz Arcanery, proprio accanto al maestro dei grifoni della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["e3745974a749abc0"] = { "Grazie a te, ora possiamo svelare i segreti dei cristalli e dei misteriosi piloni, {name}. Se ti servono altre informazioni, torna pure a trovarmi in qualsiasi momento!", "." },
  ["e376e6df7c2df30c"] = { "Bene bene, niente male. Forse POSSO insegnarti qualcosa...", "." },
  ["e377a84ee7944a78"] = { "Ho perso l'⟦Lord Valthalak's Amulet=Amuleto di Sire Valthalak⟧!", "." },
  ["e3788fe11bfcea8b"] = { "$966w, giovane {class}.", "." },
  ["e389e6732ee520a1"] = { "Le voci si sono rivelate vere, {name}?", "." },
  ["e3902c53c7fd596d"] = { "Bende, antiveleni e cose simili sono necessità inevitabili della vita nelle pianure. Vira Younghoof può insegnarti queste conoscenze. La trovi nella casa lunga sul lato ovest del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "." },
  ["e3a25f09cbc6cef0"] = { "La sala degli ufficiali", "." },
