  ["e3c4369b94f2afa8"] = { "Vorrei addestrarmi.", "." },
  ["e3c4903284fa7c91"] = { "Da bere per l'amico Sarok, e un altro per me.", "." },
  ["e3c6282061d8d893"] = { "Ci sono modi per rafforzare l'acciaio che vanno oltre il martello e la forgia, giovane viandante. Vuoi saperne di più?", "." },
  ["e3d287f40942c3c7"] = { "Hai liberato Kirith dalle sue sofferenze? Inconcepibile... e ora Trebor ti ha mandato qui a studiare i demoni e i loro servitori?\n\n<Loramus ride.>\n\nSii <grato/grata> che le fitte arcane si siano finalmente dissolte, {race}.", "." },
  ["e3dcee66fdcf761c"] = { "%s comincia a tradurre...", "." },
  ["e3e274734e188ac5"] = { "<La mappa che tieni in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto sotto la stessa ⟦Ironforge=Forgiardente⟧.\r\n\nNon sai con certezza cosa dicano le rune, scritte nel brutto linguaggio runico frastagliato dei nani ⟦Dark Iron=Ferroscuro⟧, ma puoi intuire lo scopo di queste gallerie. Mentre leggi la mappa, una folata di vento ti investe e vi senti appena una voce nanica che ti esorta a cercare un veggente della terra di nome \"Farsen\".>", "." },
  ["e3e31393d0572c48"] = { "Che la battaglia per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧ abbia inizio!", "." },
  ["e3e6e5d6c7ec20d9"] = { "Ehi, amico, tu devi andare dall'istruttore di {class}.", "." },
  ["e3e768f3d4cc57d5"] = { "{name} conquista la segheria! Se nessuno interviene, l'⟦Horde=Orda⟧ la controllerà tra 1 minuto!", "." },
  ["e3ebc23674003cc8"] = { "Chi sono i Creatori?", "." },
  ["e3f01e7fd4bc560f"] = { "Finalmente, ⟦Redridge=Crestarossa⟧. Un piacevole cambiamento rispetto alla nebbia buia e fredda di ⟦Duskwood=Boscovespro⟧.", "." },
  ["e3f9ecf6d1294ab4"] = { "Och! Bada bene a cosa ti fai incantare, <ragazzo/ragazza>. Ho fatto incantare il mio boccale perché non versasse una goccia, ma ora non riesco a berci! Che tragedia.\n\nSegui bene il mio consiglio quando vedi Gimble. Lo troverai nella sua bottega, proprio accanto al maestro dei grifoni della ⟦Great Forge=Grande Forgia⟧.", "." },
